mapper.select:
SELECT lcca.document_name,lcca.credit_attachment_id,lcca.credit_contract_id,lcca.credit_attachment_category,
lcca.description,lcca.source_id,lcca.attachment_code,lcca.order_number,lcca.creation_date,
(select wm_concat(fat.file_name) from fnd_atm_attachment fat, fnd_atm_attachment_multi faam where fat.attachment_id = faam.attachment_id
and faam.table_name = 'LON_CREDIT_ATTACHMENT' and faam.table_pk_value = lcca.credit_attachment_id
) file_name
FROM lon_credit_attachment lcca

    lcca.credit_contract_id =  #{creditContractId}
    AND lcca.credit_attachment_category = #{creditAttachmentCategory}

order by order_number,creation_date

select hba.bp_attachment_id, hba.document_name, ( SELECT wm_concat(sf.file_name) FROM sys_attachment sa, sys_file sf WHERE hba.bp_attachment_id = sa.source_key AND sa.source_type = 'lon_credit_attachment' AND sa.attachment_id = sf.attachment_id ) file_name, hba.description from lon_credit_attachment hba where 1 = 1 and hba.bp_source_type = 'lon_credit_attachment'
and hba.credit_contract_id = #{creditContractId}
GROUP BY hba.credit_attachment_id order by last_update_date desc

select * from( select hba.bp_attachment_id as bp_attachment_id, hba.document_name as document_name, sa.attachment_id attachment_id, sf.file_id as file_id, sf.file_name as file_name, sf.file_size as file_size, (select su.description from sys_user su where sf.last_updated_by = su.user_id) as upload_person, sf.last_update_date as uploadDate from lon_credit_attachment hba, sys_attachment sa, sys_file sf where hba.credit_attachment_id = sa.source_key and hba.credit_source_type = sa.source_type and sa.attachment_id = sf.attachment_id
and hba.credit_attachment_id = #{creditAttachmentId}
and hba.credit_contract_id = #{creditContractid}
) qf order by qf.uploadDate desc
